-- Test d'acceptation : 3 devis ProGBat reconstruits, à exécuter dans une transaction annulée.
BEGIN;
SELECT set_config('app.devis_rpc','on',true);
/* helper */
CREATE OR REPLACE FUNCTION pg_temp._acc_lignes(_ligne uuid, _ls jsonb) RETURNS void LANGUAGE plpgsql AS $h$
DECLARE li jsonb; n int := 0;
BEGIN
  FOR li IN SELECT * FROM jsonb_array_elements(_ls) LOOP
    n := n+1;
    IF li->>'type'='heures' THEN
      INSERT INTO devis_heures(ligne_id,poste_id,niveau,heures,par_unite,taux_vente,taux_grille,cout_revient,ordre,montant_force)
      SELECT _ligne,p.id,li->>'niveau',(li->>'heures')::numeric,true,coalesce(t.taux_vente,0),t.taux_vente,t.cout_revient,n,(li->>'montant_force')::numeric
        FROM devis_postes_ref p LEFT JOIN v_devis_taux_courants t ON t.poste_id=p.id AND t.niveau=li->>'niveau' WHERE p.code=li->>'poste';
      IF NOT FOUND THEN RAISE EXCEPTION 'Poste inconnu %', li->>'poste'; END IF;
    ELSE
      INSERT INTO devis_lignes_libres(ligne_id,categorie,designation,quantite,prix_forfait,coefficient,par_unite,ordre,heures_info,poste_info_id)
      VALUES(_ligne,'forfait',li->>'designation',(li->>'quantite')::numeric,(li->>'prix_unitaire_vente')::numeric,1,true,n,
        NULLIF((li->>'heures_info')::numeric,0),(SELECT id FROM devis_postes_ref WHERE code=li->>'poste_info'));
    END IF;
  END LOOP;
END $h$;
