'::jsonb) LOOP
    k := k+1; a := dj->'attendu';
    INSERT INTO devis(affaire_id,numero,statut,redige_dans_staffing,version,statut_redaction,tva_pct,numero_progbat,date_devis,remise_mode,remise_valeur)
      VALUES(v_aff,'TEST-'||k,'brouillon',true,900+k,'brouillon',20,dj->>'numero_progbat',current_date,
        CASE WHEN (a->>'remise')::numeric<>0 THEN 'montant' ELSE 'aucune' END, NULLIF(abs((a->>'remise')::numeric),0)) RETURNING id INTO v_d;
    o := 0;
    FOR ch IN SELECT * FROM jsonb_array_elements(dj->'chapitres') LOOP
      o := o+1;
      v_type := CASE WHEN ch->>'type'='option_incluse' THEN 'option'
                     WHEN ch->>'titre' ILIKE 'Suivi de projet%' THEN 'chapitre_suivi'
                     WHEN ch->>'titre' ILIKE 'DEPOSE%' THEN 'chapitre_depose'
                     WHEN ch->>'titre' ILIKE '%MONTAGE%' THEN 'chapitre_pose'
                     ELSE 'zone' END;
      INSERT INTO devis_lignes(devis_id,parent_id,type,ordre,libelle,quantite,option_incluse)
        VALUES(v_d,NULL,v_type,o,CASE WHEN v_type='zone' THEN 'Fabrication' ELSE ch->>'titre' END,1,ch->>'type'='option_incluse')
        RETURNING id INTO v_ch;
      FOR ob IN SELECT * FROM jsonb_array_elements(ch->'objets') LOOP
        INSERT INTO devis_lignes(devis_id,parent_id,type,ordre,libelle,quantite)
          VALUES(v_d,v_ch,'objet',(ob->>'n')::text::numeric*0+o*100+coalesce((SELECT count(*) FROM devis_lignes WHERE parent_id=v_ch),0),ob->>'titre',(ob->>'quantite')::numeric)
          RETURNING id INTO v_obj;
        PERFORM pg_temp._acc_lignes(v_obj, ob->'lignes');
      END LOOP;
      PERFORM pg_temp._acc_lignes(v_ch, ch->'lignes');
    END LOOP;
    a := dj->'attendu';
    c := devis_calculer_interne(v_d);
    INSERT INTO _res VALUES(dj->>'numero_progbat',
      (c->>'total_ht')::numeric=(a->>'total_ht')::numeric AND (c->>'remise')::numeric=(a->>'remise')::numeric
      AND (c->>'net_ht')::numeric=(a->>'net_ht')::numeric AND (c->>'tva')::numeric=(a->>'tva')::numeric
      AND (c->>'ttc')::numeric=(a->>'ttc')::numeric,
      jsonb_build_object('total_ht',c->'total_ht','remise',c->'remise','net_ht',c->'net_ht','tva',c->'tva','ttc',c->'ttc',
        'heures_metier',(SELECT jsonb_object_agg(coalesce(m.nom,e.key),e.value) FROM jsonb_each(c->'heures_metier') e LEFT JOIN metiers m ON m.id::text=e.key)), a);
  END LOOP;
END $t$;
SELECT * FROM _res;
ROLLBACK;
